def apply_fixes(filepath, fixes):
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    
    for idx, new_text in fixes.items():
        if idx < len(lines):
            lines[idx] = new_text
            
    with open(filepath, 'w', encoding='utf-8') as f:
        f.writelines(lines)

apply_fixes(ru_file, ru_dict)
apply_fixes(ua_file, ua_dict)

print("Applied 31 absolute line replacements securely to RU and UA files.")
